// x64 layouts mirror FWPM_FILTER0, FWPM_FILTER_CONDITION0 and FWPM_SUBLAYER0.
// No display strings, condition values, application identifiers, or IPs are returned.
[StructLayout(LayoutKind.Sequential)] public struct WfpDisplay0 {public IntPtr name,description;}
[StructLayout(LayoutKind.Sequential)] public struct WfpBlob0 {public uint size;public IntPtr data;}
[StructLayout(LayoutKind.Sequential)] public struct WfpValue0 {public uint type;public IntPtr value;}
[StructLayout(LayoutKind.Sequential)] public struct WfpAction0 {public uint type;public Guid key;}
[StructLayout(LayoutKind.Explicit,Size=16)] public struct WfpContext0 {[FieldOffset(0)] public ulong raw;[FieldOffset(0)] public Guid providerContext;}
[StructLayout(LayoutKind.Sequential)] public struct WfpFilter0 {public Guid key;public WfpDisplay0 display;public uint flags;public IntPtr provider;public WfpBlob0 providerData;public Guid layer,subLayer;public WfpValue0 weight;public uint conditionCount;public IntPtr conditions;public WfpAction0 action;public WfpContext0 context;public IntPtr reserved;public ulong id;public WfpValue0 effectiveWeight;}
[StructLayout(LayoutKind.Sequential)] public struct WfpCondition0 {public Guid field;public uint match;public WfpValue0 value;}
[StructLayout(LayoutKind.Sequential)] public struct WfpSubLayer0 {public Guid key;public WfpDisplay0 display;public uint flags;public IntPtr provider;public WfpBlob0 providerData;public ushort weight;}
